typedef int axis_id_t;
typedef float rational_t;

enum PS2_Axes
{
  JOY_PS2_DX,
  JOY_PS2_DY,
  JOY_PS2_X,
  JOY_PS2_Y,
  JOY_PS2_LX,
  JOY_PS2_LY,
  JOY_PS2_BTNL3,
  JOY_PS2_RX,
  JOY_PS2_RY,
  JOY_PS2_BTNR3,
  JOY_PS2_BTNX,
  JOY_PS2_BTNO,
  JOY_PS2_DUMMMY1,
  JOY_PS2_BTNSQ,
  JOY_PS2_BTNTR,
  JOY_PS2_DUMMMY2,
  JOY_PS2_BTNL1,
  JOY_PS2_BTNR1,
  JOY_PS2_BTNL2,
  JOY_PS2_BTNR2,
  JOY_PS2_START,
  JOY_PS2_SELECT,
  JOY_PS2_DISCONNECT,
  JOY_PS2_NUM_AXES
};

#define assert(expr) ((void)0)

class AISurferController
{
  char padding[0x9c];
  float X, Y, XRight, YRight;
  bool ButtonX, ButtonO, ButtonSq, ButtonTr;
  bool ButtonL1, ButtonL2, ButtonL3, ButtonR1,ButtonR2,ButtonR3;
  bool ButtonSelect,ButtonStart;
  float oldX, oldY, oldXRight, oldYRight;
  bool oldButtonX, oldButtonO, oldButtonSq, oldButtonTr;
  bool oldButtonL1, oldButtonL2, oldButtonL3, oldButtonR1, oldButtonR2, oldButtonR3;
  bool oldButtonSelect,oldButtonStart;

public:
  rational_t get_axis_delta(axis_id_t axis, int control_axis) const;
};

rational_t AISurferController::get_axis_delta(axis_id_t axis, int control_axis ) const
{
  switch (axis) 
  {
    case JOY_PS2_X: // left analog horiz
      return X - oldX;

    case JOY_PS2_Y: // left analog vert
      return Y - oldY;

    case JOY_PS2_DX: // just Dpad
      if (oldX < 0)
      {
        if (X < 0)
          return 0;
        else if (X > 0)
          return 2;
        else 
          return 1;

      }
      else if (oldX > 0)
      {
        if (X < 0)
          return 0;
        else if (X > 0)
          return -2;
        else 
          return -1;

      }
      else
      {
        if (X == 0)
          return 0;
        else if (X < 0)
          return -1;
        else 
          return 1;
      }

    case JOY_PS2_DY: // just Dpad -1 = up
      if (oldY < 0)
      {
        if (Y < 0)
          return 0;
        else if (Y > 0)
          return 2;
        else 
          return 1;

      }
      else if (oldY > 0)
      {
        if (Y < 0)
          return 0;
        else if (Y > 0)
          return -2;
        else 
          return -1;

      }
      else
      {
        if (Y == 0)
          return 0;
        else if (Y < 0)
          return -1;
        else 
          return 1;
      }


    case JOY_PS2_LX: //  - 1 = left
      return X - oldX;
    case JOY_PS2_LY: // -1 = up
      return Y - oldY;
    case JOY_PS2_RX: 
      return XRight - oldXRight;
    case JOY_PS2_RY: 
      return YRight - oldYRight;

    case JOY_PS2_BTNL3: // L3
      return ButtonL3 - oldButtonL3;
    case JOY_PS2_BTNR3: 
      return ButtonR3 - oldButtonR3;
    case JOY_PS2_BTNX:  // A (ps2 x)
      return ButtonX - oldButtonX;
    case JOY_PS2_BTNO:  // B (ps2 o)
        return ButtonO - oldButtonO;
    case JOY_PS2_BTNSQ: // X (ps2 sq)
        return ButtonSq - oldButtonSq;
    case JOY_PS2_BTNTR: // Y (ps2 tr)
        return ButtonTr - oldButtonTr;

    case JOY_PS2_BTNR1: // C (ps2 R1)
        return ButtonR1 - oldButtonR1;
    case JOY_PS2_BTNR2: // R (ps2 R2)
        return ButtonR2 - oldButtonR2;

    case JOY_PS2_BTNL1: // Z (ps2 L1)
        return ButtonL1 - oldButtonL1;
    case JOY_PS2_BTNL2: // L (ps2 L2)
        return ButtonL2 - oldButtonL2;


    case JOY_PS2_START: // Start
      return ButtonStart - oldButtonStart;
    case JOY_PS2_SELECT:
      return ButtonSelect - oldButtonSelect;

    default:
      assert("ps2_joypad_device::get_axis_state illegal axis queried." == 0);
      return 0.0f;

  }

}
